const UAS = [
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Safari/605.1.15',
  'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:125.0) Gecko/20100101 Firefox/125.0',
  'Mozilla/5.0 (iPad; CPU OS 17_4 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Mobile/15E148 Safari/604.1'
];
const ua = UAS[Math.floor(Math.random() * UAS.length)];
return [{ json: { userAgent: ua } }];

// ── 99.co: Parse + Filter + Deduplicate ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentIds) staticData.sentIds = {};

const now = Date.now();
for (const id in staticData.sentIds) {
  if (now - staticData.sentIds[id] > 86400000) delete staticData.sentIds[id];
}

const raw = $input.first().json;
// 99.co API: data.listings or results
const listings = raw.data?.listings || raw.data?.results || raw.listings || raw.results || [];
if (!Array.isArray(listings)) {
  console.log('99co: unexpected shape', JSON.stringify(raw).slice(0, 200));
  return [];
}

const output = [];

for (const listing of listings) {
  // ── Price filter ──
  const priceRaw = listing.price_formatted?.raw ||
    listing.price?.amount || listing.price || 0;
  const price = parseInt(String(priceRaw).replace(/\D/g, ''));
  if (!price || price < 300000 || price > 800000) continue;

  // ── Location ──
  const locText = [
    listing.address, listing.city, listing.district,
    listing.area_name, listing.title, listing.name
  ].filter(Boolean).join(' ').toLowerCase();
  if (!locText.includes('surabaya') && !locText.includes('sby') &&
      !locText.includes('jawa timur')) continue;

  // ── Images ──
  const rawPhotos = listing.photos || listing.images || listing.pictures || [];
  const images = rawPhotos
    .map(p => {
      if (typeof p === 'string') return p;
      return p?.url || p?.full_url || p?.photo_url ||
        p?.sizes?.large || p?.sizes?.medium || p?.src || '';
    })
    .filter(u => u && u.startsWith('http'))
    .slice(0, 5);
  if (images.length === 0) continue;

  // ── Dedup ──
  const uid = '99co_' + (listing.id || listing.listing_id || listing.slug || '');
  if (!uid.replace('99co_', '') || staticData.sentIds[uid]) continue;
  staticData.sentIds[uid] = now;

  // ── URL ──
  const slug = listing.slug || listing.id;
  const url = listing.url || listing.link ||
    `https://www.99.co/id/properti/${slug}`;

  output.push({
    json: {
      source: '99co',
      title: listing.title || listing.name || 'Kos Surabaya',
      price,
      location: [
        listing.address, listing.district, listing.city
      ].filter(Boolean).join(', ') || 'Surabaya',
      url: url.startsWith('http') ? url : 'https://www.99.co' + url,
      description: (listing.description || listing.short_description || '').slice(0, 500),
      images,
      scraped_at: new Date().toISOString()
    }
  });
}

console.log(`99co: ${output.length} listings passed filters`);
return output;
